namespace VisionPlugins.Calibration;

public sealed record NImageSolveFrame(NImageDetectedBoard Board,NImagePose Pose);
public readonly record struct NImageRelativeMotion(float X,float Y,float Scale,float Rotation,double RegistrationError);
public sealed record NImageTranslationSolveResult(uint ErrorCode,IReadOnlyList<double> Matrix,double AverageRegistrationError,double MaximumRegistrationError,IReadOnlyList<NImagePose> ImageMotion){public int MaximumRegistrationFrame{get;init;}public double BoardScale{get;init;}public IReadOnlyList<NImageRelativeMotion> RelativeMotion{get;init;}=Array.Empty<NImageRelativeMotion>();}
/// <summary>Independent translation branch of 7d12e0. Coded-board recognition
/// and rotation calibration are separate stages; no original native dependency.</summary>
public static class NImageSolveTranslation {
 public static NImageTranslationSolveResult Solve(IReadOnlyList<NImageSolveFrame> frames){
  if(frames.Count is <4 or >15)return new(0x10000019,[],0,0,[]);var boardMatrices=new List<double[]>();
  foreach(var frame in frames){var pairs=frame.Board.Points.Select(p=>new NPointPair(p.X,p.Y,p.IndexX*frame.Board.GridPitch,p.IndexY*frame.Board.GridPitch)).ToArray();var fit=NPointSolver.Solve(pairs,[],new(2,1));if(fit.ErrorCode!=0)return new(fit.ErrorCode,[],0,0,[]);boardMatrices.Add(fit.Matrix);}
  var motion=new List<NImagePose>{new(0,0,0)};double error=0,maxError=0;int maxFrame=0;var relativeMotions=new List<NImageRelativeMotion>();
  for(int i=1;i<frames.Count;i++){var relative=Multiply(Inverse(boardMatrices[i]),boardMatrices[i-1]);float dx=(float)(relative[2]/relative[8]),dy=(float)(relative[5]/relative[8]);motion.Add(new((float)((float)motion[^1].X+dx),(float)((float)motion[^1].Y+dy),0));var previous=frames[i-1].Board.Points.ToDictionary(p=>(p.IndexX,p.IndexY));double sum=0;int count=0;foreach(var p in frames[i].Board.Points)if(previous.TryGetValue((p.IndexX,p.IndexY),out var before)){float ex=(float)(dx-(float)(p.X-before.X)),ey=(float)(dy-(float)(p.Y-before.Y));sum+=Math.Sqrt(ex*ex+ey*ey);count++;}double average=count>1?sum/(count+float.Epsilon):0;error+=average;if(average>maxError){maxError=average;maxFrame=i-1;}float scale=(MathF.Sqrt((float)(relative[0]*relative[0]+relative[1]*relative[1]))+MathF.Sqrt((float)(relative[3]*relative[3]+relative[4]*relative[4])))*.5f;relativeMotions.Add(new(dx,dy,scale,MathF.Atan2((float)relative[3],(float)relative[0]),average));}
  var offsets=frames.Select((frame,i)=>new NPointPair(motion[i].X,motion[i].Y,frame.Pose.X-frames[0].Pose.X,frame.Pose.Y-frames[0].Pose.Y)).ToArray();var calibration=NPointSolver.Solve(offsets,[],new(2,1));if(calibration.ErrorCode!=0)return new(calibration.ErrorCode,[],error/frames.Count,maxError,motion.AsReadOnly());var h=calibration.Matrix;double bestError=double.PositiveInfinity;
  // Original 7d12e0 enumerates four-frame subsets, selecting mean inverse-projection error over the full motion sequence.
  for(int a=0;a<offsets.Length-3;a++)for(int b=a+1;b<offsets.Length-2;b++)for(int c=b+1;c<offsets.Length-1;c++)for(int d=c+1;d<offsets.Length;d++){
   var fit=NPointSolver.Solve(new[]{offsets[a],offsets[b],offsets[c],offsets[d]},[],new(2,1));if(fit.ErrorCode!=0)continue;double[] inverse;try{inverse=Inverse(fit.Matrix);}catch(InvalidOperationException){continue;}double total=0;foreach(var point in offsets){var predicted=NPointSolver.Transform(inverse,point.WorldX,point.WorldY);total+=Math.Sqrt(Math.Pow(predicted.X-point.ImageX,2)+Math.Pow(predicted.Y-point.ImageY,2));}double mean=total/offsets.Length;if(mean<bestError){bestError=mean;h=fit.Matrix;}
  }
  var firstInverse=Inverse(boardMatrices[0]);double originX=firstInverse[2]/firstInverse[8],originY=firstInverse[5]/firstInverse[8];h[2]=-originX*h[0]-originY*h[1];h[5]=-originX*h[3]-originY*h[4];return new(0,Array.AsReadOnly(h),error/frames.Count,maxError,motion.AsReadOnly()){MaximumRegistrationFrame=maxFrame,BoardScale=(Math.Sqrt(boardMatrices[0][0]*boardMatrices[0][0]+boardMatrices[0][1]*boardMatrices[0][1])+Math.Sqrt(boardMatrices[0][3]*boardMatrices[0][3]+boardMatrices[0][4]*boardMatrices[0][4]))*.5,RelativeMotion=relativeMotions.AsReadOnly()};
 }
 static double[] Multiply(double[] a,double[] b){var c=new double[9];for(int r=0;r<3;r++)for(int col=0;col<3;col++){float sum=0;for(int k=0;k<3;k++)sum+=(float)a[3*r+k]*(float)b[3*k+col];c[3*r+col]=sum;}return c;}
 static double[] Inverse(double[] matrix){var m=matrix.Select(v=>(float)v).ToArray();float d=(((m[8]*m[0]*m[4]+m[6]*m[1]*m[5]+m[7]*m[2]*m[3])-m[7]*m[0]*m[5])-m[8]*m[1]*m[3])-m[6]*m[4]*m[2];if(Math.Abs(d)<1e-20)throw new InvalidOperationException("Degenerate calibration");float inv=1/d;return [(m[4]*m[8]-m[5]*m[7])*inv,(m[2]*m[7]-m[1]*m[8])*inv,(m[1]*m[5]-m[2]*m[4])*inv,(m[5]*m[6]-m[3]*m[8])*inv,(m[0]*m[8]-m[2]*m[6])*inv,(m[2]*m[3]-m[0]*m[5])*inv,(m[3]*m[7]-m[4]*m[6])*inv,(m[1]*m[6]-m[0]*m[7])*inv,(m[0]*m[4]-m[1]*m[3])*inv];}
}
